    import collections
    for i in range(H):
        for j in range(W):
            if g[i][j]==v and (i,j) not in seen:
                q=[(i,j)];seen.add((i,j));c=[]
                while q:
                    y,x=q.pop()
                    c.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
